export function modelProfiles(values: unknown, legacyIds: string[]): ChatModelProfile[] {
  if (!Array.isArray(values)) throw new Error("API Chat model profiles must be an array.");
  const result: ChatModelProfile[] = values.map(value => {
    if (!value || typeof value.id !== "string" || !value.id.trim() || !["active", "deprecated"].includes(value.status)
      || !Number.isSafeInteger(value.contextWindow) || value.contextWindow < 256
      || (value.deprecatedAt !== undefined && !Number.isFinite(Date.parse(value.deprecatedAt)))) throw new Error("Invalid API Chat model profile.");
    for (const price of [value.inputPricePerMillion, value.outputPricePerMillion]) {
      if (price !== undefined && (typeof price !== "number" || !Number.isFinite(price) || price < 0)) throw new Error("Model prices must be non-negative numbers.");
    }
    const maxOutputTokens = value.maxOutputTokens ?? Math.min(4096, Math.floor(value.contextWindow / 4));
    if (!Number.isSafeInteger(maxOutputTokens) || maxOutputTokens < 1 || maxOutputTokens >= value.contextWindow) throw new Error("Invalid model output limit.");
    return {
      id: value.id, model: value.model || value.id, label: value.label || value.id, status: value.status,
      contextWindow: value.contextWindow, maxOutputTokens, deprecatedAt: value.deprecatedAt,
      inputPricePerMillion: value.inputPricePerMillion, outputPricePerMillion: value.outputPricePerMillion,
      currency: value.currency || "USD", includeUsage: value.includeUsage === true,
      outputTokenParameter: value.outputTokenParameter === "max_tokens" ? "max_tokens" : "max_completion_tokens",
    };
  });
  if (new Set(result.map(profile => profile.id)).size !== result.length) throw new Error("Model profile IDs must be unique.");
  for (const id of legacyIds) if (id && !result.some(profile => profile.id === id)) result.push({
    id, model: id, label: id, status: "unknown", contextWindow: 4096, maxOutputTokens: 1024,
    currency: "USD", includeUsage: false, outputTokenParameter: "max_tokens",
  });
  return result;
}

export function assertModelAvailable(profile: ChatModelProfile, now = Date.now()): void {
  if (profile.status === "deprecated" || (profile.deprecatedAt && Date.parse(profile.deprecatedAt) <= now)) {
    throw new Error("This model is deprecated. Select an available model.");
  }
}

export function estimateInputTokens(messages: ApiChatMessage[]): number {
  return messages.reduce((sum, message) => sum + Buffer.byteLength(message.content + (message.tool_calls ? JSON.stringify(message.tool_calls) : ""), "utf8") + 32, 32);
}

export function validateBudget(profile: ChatModelProfile, contextWindow: number, outputTokens: number, messages: ApiChatMessage[]): number {
  assertModelAvailable(profile);
  if (!Number.isSafeInteger(contextWindow) || contextWindow < 256 || contextWindow > profile.contextWindow) throw new Error("Context budget exceeds the model's configured window.");
  if (!Number.isSafeInteger(outputTokens) || outputTokens < 1 || outputTokens > profile.maxOutputTokens || outputTokens >= contextWindow) throw new Error("Output budget exceeds the configured model limit.");
  const input = estimateInputTokens(messages);
  if (input + outputTokens > contextWindow) throw new Error(`Context budget exceeded (~${input} input + ${outputTokens} output tokens). Reduce context/history or increase the budget.`);
  return input;
}

export function estimateCost(profile: Pick<ChatModelProfile, "inputPricePerMillion" | "outputPricePerMillion">, inputTokens: number, outputTokens: number): number | undefined {
  if (profile.inputPricePerMillion === undefined || profile.outputPricePerMillion === undefined) return undefined;
  return (inputTokens * profile.inputPricePerMillion + outputTokens * profile.outputPricePerMillion) / 1_000_000;
}

private defaultModel(): { provider: "vscode" | "openai-compatible" | "azure-openai"; profile: ChatModelProfile } | undefined {
  const saved = this.extension.globalState?.get<{ provider: "vscode" | "openai-compatible" | "azure-openai"; profile: ChatModelProfile }>("apiChat.defaultModel");
  if (!saved || !["vscode", "openai-compatible", "azure-openai"].includes(saved.provider) || !saved.profile || typeof saved.profile.id !== "string" || typeof saved.profile.model !== "string"
    || !Number.isSafeInteger(saved.profile.contextWindow) || saved.profile.contextWindow < 256 || !Number.isSafeInteger(saved.profile.maxOutputTokens) || saved.profile.maxOutputTokens < 1 || saved.profile.maxOutputTokens >= saved.profile.contextWindow) return undefined;
  if (saved.provider === "vscode" && !saved.profile.id.startsWith("vscode:")) return undefined;
  return saved;
}

private createChat(store = this.store!): ApiConversation {
  const chat = store.create();
  const saved = this.defaultModel();
  if (saved) {
    chat.modelProvider = saved.provider;
    if (saved.provider === "vscode") { chat.vscodeModelId = saved.profile.id; chat.vscodeModelLabel = saved.profile.label; }
    else chat.modelProfileId = saved.profile.id;
    store.save(chat);
  }
  return chat;
}

private settings(chat = this.chat) {
  const cfg = vscode.workspace.getConfiguration("personalKnowledge");
  const activityCreditLimitDefault = cfg.get<number>("apiChatActivityCreditLimit", 200);
  const activityCreditLimit = chat?.activityCreditLimit ?? activityCreditLimitDefault;
  if (!validActivityCreditLimit(activityCreditLimitDefault) || !validActivityCreditLimit(activityCreditLimit)) {
    throw new Error("Choose an activity credit limit from -1 to 1,000,000,000.");
  }
  const activityReviewMinutes = cfg.get<number>("apiChatActivityReviewMinutes", 20);
  if (!Number.isSafeInteger(activityReviewMinutes) || activityReviewMinutes < 1 || activityReviewMinutes > 1440) {
    throw new Error("Choose an activity review interval of 1-1440 minutes.");
  }
  const provider = chat?.modelProvider || cfg.get<"vscode" | "openai-compatible" | "azure-openai">("apiChatProvider", "openai-compatible");
  const defaultModel = cfg.get<string>("aiModel", "gpt-4o-mini");
  const available = provider === "vscode" ? this.vscodeModels.map(vscodeModelProfile) : [];
  const saved = this.defaultModel();
  const remembered = saved?.provider === provider && saved.profile.id === (provider === "vscode" ? chat?.vscodeModelId : chat?.modelProfileId) ? saved.profile : undefined;
  if (provider === "vscode" && remembered && !available.some(profile => profile.id === remembered.id)) available.push(remembered);
  const selected = provider === "vscode" ? available.find(profile => profile.id === chat?.vscodeModelId) || (!chat?.vscodeModelId ? available[0] : undefined) : undefined;
  const configured = cfg.get<unknown>("apiChatModelProfiles", []);
  const entries = Array.isArray(configured) ? configured : [];
  const profiles = provider === "vscode" ? available : modelProfiles([...entries, ...(remembered && !entries.some(profile => profile?.id === remembered.id) ? [remembered] : [])], [defaultModel, ...cfg.get<string[]>("apiChatModels", []), chat?.modelProfileId || ""]);
  const selectedProfile = provider === "vscode" ? selected || { ...modelProfiles([], ["__vscode_unavailable__"])[0], label: chat?.vscodeModelLabel || "Not connected" } : profiles.find(profile => profile.id === (chat?.modelProfileId || defaultModel))!;
  return {
    provider, needsModelConnection: provider === "vscode" && !selected,
    endpoint: provider === "vscode" ? "" : cfg.get<string>("aiEndpoint", ""), model: selectedProfile.model,
    profiles, selectedProfile,
    contextWindow: chat?.contextWindow || selectedProfile.contextWindow,
    maxOutputTokens: chat?.maxOutputTokens || selectedProfile.maxOutputTokens,
    models: cfg.get<string[]>("apiChatModels", []), apiVersion: cfg.get<string>("aiAzureApiVersion", "2024-06-01"),
    timeoutMs: Math.min(86400, Math.max(10, cfg.get<number>("apiChatTimeoutSeconds", 1800))) * 1000,
    loopReviewAfterMs: Math.min(1440, Math.max(1, cfg.get<number>("apiChatLoopReviewMinutes", 30))) * 60_000,
    activityCreditLimit, activityCreditLimitDefault, activityReviewMs: activityReviewMinutes * 60_000,
    maxToolRounds: chatToolRoundLimit(cfg.get<number>("apiChatMaxToolRounds", 30)),
    loopExemptTools: cfg.get<string[]>("apiChatLoopExemptTools", defaultLoopExemptTools),
  };
}

private readApiKey(signal: AbortSignal): Promise<string> {
  return new Promise((resolve, reject) => {
    const cancel = () => { signal.removeEventListener("abort", cancel); reject(new Error("Request cancelled.")); };
    signal.addEventListener("abort", cancel, { once: true });
    if (signal.aborted) { cancel(); return; }
    this.extension.secrets.get("personalKnowledge.aiApiKey").then(key => {
      signal.removeEventListener("abort", cancel); resolve(key || "");
    }, () => { signal.removeEventListener("abort", cancel); reject(new Error("Cannot read the API key from SecretStorage.")); });
  });
}

visualizationLibrary(): { groups: Array<{ id: string; name: string }>; chats: Array<Record<string, unknown>> } {
  if (this.disposed) throw new Error("The PKM Chat Host is closed.");
  const store = this.openStore();
  const chats = store.list().map(item => {
    const live = this.running.has(item.id) ? this.chats.get(item.id) : undefined;
    return { id: item.id, title: live?.title || item.title, updatedAt: item.updatedAt, groupId: item.groupId,
      status: live ? apiChatStatus(live, true, this.awaitingInput.has(item.id)) : item.status,
      workerParentChatId: item.workerParentChatId, workerTreeId: item.workerTreeId,
      workerManager: live ? live.messages.some(message => message.delegations?.length) : item.workerManager };
  });
  return { groups: store.library.read().groups.map(group => ({ id: group.id, name: group.name })), chats };
}

async readVisualization(chatId: string, method: string, params: Record<string, unknown>): Promise<unknown> {
  if (this.disposed) throw new Error("The PKM Chat Host is closed.");
  if (typeof chatId !== "string" || !/^[a-f0-9-]{36}$/.test(chatId)) throw new Error("Choose a PKM Chat.");
  const store = this.openStore();
  let chat = this.running.has(chatId) ? this.chats.get(chatId) : undefined;
  if (!chat) {
    try { chat = store.load(chatId, false); }
    catch { throw new Error("This Chat is unavailable in the current Knowledge Root."); }
  }
  return this.visualizationRequest(chat, method, params);
}

/** Opens the inspected Chat, or a recorded retrieval source of it, from the Visualization window. */
async openVisualizationTarget(chatId: string, sourceUri?: string): Promise<void> {
  if (this.disposed) throw new Error("The PKM Chat Host is closed.");
  if (!vscode.workspace.isTrusted) throw new Error("Trust this workspace before opening execution records.");
  if (typeof chatId !== "string" || !/^[a-f0-9-]{36}$/.test(chatId)) throw new Error("Choose a PKM Chat.");
  const chats = this.openStore().list();
  const open = (id: string) => {
    const item = chats.find(entry => entry.id === id);
    if (!item) throw new Error("This Chat is unavailable in the current Knowledge Root or is in Trash.");
    return this.openPkmChat(chatPkmUrl(item.workspaceNamespace, item.id));
  };
  if (sourceUri === undefined) return open(chatId);
  if (typeof sourceUri !== "string" || sourceUri.length > 2048) throw new Error("This source has no navigable PKM path.");
  const memory = /^pkm:\/\/chats\/([a-f0-9-]{36})\/memory\//.exec(sourceUri);
  if (memory) return open(memory[1]);
  let parsed;
  try { parsed = parsePkmLocator(sourceUri); }
  catch { throw new Error("This source has no navigable PKM path."); }
  if (parsed.kind === "chat") return this.openPkmChat(parsed.locator);
  await vscode.commands.executeCommand("personalKnowledge.goToPkmPath", parsed.locator);
}

export function vscodeModelProfile(model: VscodeChatModel): ChatModelProfile {
  if (!Number.isSafeInteger(model.maxInputTokens) || model.maxInputTokens < 256) throw new VscodeChatError("This model does not report a usable input limit.");
  return {
    id: `vscode:${encodeURIComponent(model.vendor)}:${encodeURIComponent(model.id)}`, model: model.id,
    label: `${model.name} · ${model.vendor === "copilot-sdk" ? "Copilot SDK" : model.vendor}`, status: "active", contextWindow: model.maxInputTokens,
    maxOutputTokens: Math.min(Number.isSafeInteger(model.maxOutputTokens) && model.maxOutputTokens! > 0 ? model.maxOutputTokens! : 4096, Math.floor(model.maxInputTokens / 4)),
    currency: "", includeUsage: false, outputTokenParameter: "max_tokens",
    imageInput: model.capabilities?.imageInput === true,
  };
}

export async function discoverVscodeModels(host = vscode, signal?: AbortSignal, vendor?: "copilot" | "copilot-sdk"): Promise<VscodeChatModel[]> {
  if (vendor !== "copilot-sdk" && !host.lm?.selectChatModels) throw new Error("This VS Code version does not provide the Language Model API. Use an API provider instead.");
  try {
    if (signal?.aborted) throw new Error("Request cancelled.");
    // Neither provider's startup should wait for the other provider's catalog.
    const pending = Promise.all([
      Promise.resolve().then(() => vendor === "copilot-sdk" ? [] : vendor ? host.lm.selectChatModels({ vendor }) : host.lm.selectChatModels()),
      vendor !== "copilot" && host.authentication ? discoverCopilotSdkModels(host, signal) : Promise.resolve([]),
    ]);
    const [nativeModels, sdkModels] = signal ? await abortable(pending, signal) : await pending;
    const models = [...nativeModels.filter(model => model.vendor !== "copilotcli" && (!vendor || model.vendor === vendor)), ...sdkModels as unknown as VscodeChatModel[]];
    if (signal?.aborted) throw new Error("Request cancelled.");
    if (!models.length) throw new Error("No VS Code models callable through the Language Model API are available. Copilot CLI catalog-only entries are excluded. Sign in to a request-capable provider or configure an API connection.");
    return models;
  } catch (error) {
    if (signal?.aborted) throw new Error("Request cancelled.");
    if (error instanceof Error && error.message.startsWith("No VS Code models")) throw error;
    throw new Error("Cannot access VS Code models. Check sign-in, extension permission and your organization policy.");
  }
}

const profiles = modelProfiles([
    { id: "active", status: "active", contextWindow: 8192, maxOutputTokens: 2048, inputPricePerMillion: 2, outputPricePerMillion: 8 },
    { id: "retired", status: "deprecated", contextWindow: 8192 },
    { id: "expired", status: "active", contextWindow: 8192, deprecatedAt: "2020-01-01" },
  ], ["unknown"]);
  assert.strictEqual(profiles[3].status, "unknown");
  assert.strictEqual(profiles[3].contextWindow, 4096);
  assert.throws(() => assertModelAvailable(profiles[1]), /deprecated/);
  assert.throws(() => assertModelAvailable(profiles[2]), /deprecated/);
  assert.throws(() => validateBudget(profiles[0], 16384, 1024, base.messages), /window/);
  assert.throws(() => validateBudget(profiles[0], 8192, 4096, base.messages), /output/i);
  assert.throws(() => validateBudget(profiles[0], 256, 128, [{ role: "user", content: "x".repeat(200) }]), /exceeded/);
  assert.strictEqual(estimateInputTokens([{ role: "user", content: "\u4f60\u597d" }]), 70);
  assert.strictEqual(estimateCost(profiles[0], 1000, 500), 0.006);
  assert.strictEqual(estimateCost(profiles[3], 1000, 500), undefined);
